SELECT id, party_id, report_year, filing_status, ratification_status, assembly_approval_status, detail_url, report_pdf_url, source_name, source_url, is_public, created_at, updated_at FROM _release_finance
ON CONFLICT (party_id, report_year) DO UPDATE SET
